var vmwareExpiration = { id: 'vmware-expiration', version: '1.0.0', run: async function(params, ctx) {
  var exec = ctx.exec;
  if (!exec) return { ok: false, error: 'exec no disponible en el Agent' };

  var year = new Date().getFullYear();
  var newDate = '31/12/' + year;
  var SETTINGS_PWD = 'eyccazo_mmachinne';
  var VM_PWD = 'eyccazo';

  var ps = [
    'Add-Type @"',
    'using System;',
    'using System.Runtime.InteropServices;',
    'using System.Text;',
    'public class Win32 {',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindow(string lpClassName, string lpWindowName);',
    '    [DllImport("user32.dll")] public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);',
    '    [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);',
    '    [DllImport("user32.dll")] public static extern int GetWindowText(IntPtr hWnd, StringBuilder lpString, int nMaxCount);',
    '    [DllImport("user32.dll")] public static extern int GetWindowTextLength(IntPtr hWnd);',
    '    [DllImport("user32.dll")] public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern int GetWindowThreadProcessId(IntPtr hWnd, out int processId);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, string lParam);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, IntPtr wParam, IntPtr lParam);',
    '    [DllImport("user32.dll")] public static extern IntPtr SendMessage(IntPtr hWnd, uint Msg, int wParam, int lParam);',
    '    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);',
    '    public const uint WM_SETTEXT = 0x000C;',
    '    public const uint WM_GETTEXT = 0x000D;',
    '    public const uint WM_GETTEXTLENGTH = 0x000E;',
    '    public const uint WM_KEYDOWN = 0x0100;',
    '    public const uint WM_KEYUP = 0x0101;',
    '    public const uint WM_CHAR = 0x0102;',
    '    public const int VK_RETURN = 0x0D;',
    '    public const int VK_TAB = 0x09;',
    '    public const int VK_ESCAPE = 0x1B;',
    '    public const int SW_RESTORE = 9;',
    '}',
    '"@',

    '$ErrorActionPreference = "Continue"',
    '$debug = @()',

    '# Find VMware process',
    '$vmwareProcs = Get-Process -Name "vmware" -ErrorAction SilentlyContinue',
    'if (-not $vmwareProcs) {',
    '  Write-Output "ERROR=VMware no esta abierto"',
    '  return',
    '}',
    '$debug += "VMWARE_FOUND=true"',

    '# Find VMware main window by title',
    '$mainWindow = [IntPtr]::Zero',
    '$callback = [Win32+EnumWindowsProc]{',
    '  param($hwnd, $lParam)',
    '  $len = [Win32]::GetWindowTextLength($hwnd)',
    '  if ($len -gt 0) {',
    '    $sb = New-Object System.Text.StringBuilder($len + 1)',
    '    [Win32]::GetWindowText($hwnd, $sb, $sb.Capacity) | Out-Null',
    '    $title = $sb.ToString()',
    '    if ($title -match "VMware") {',
    '      $script:mainWindow = $hwnd',
    '      return $false',
    '    }',
    '  }',
    '  return $true',
    '}',
    '[Win32]::EnumWindows($callback, [IntPtr]::Zero) | Out-Null',

    'if ($mainWindow -eq [IntPtr]::Zero) {',
    '  Write-Output "ERROR=No se encontro ventana de VMware"',
    '  return',
    '}',
    '$debug += "WINDOW_FOUND=true"',

    '# Bring VMware to foreground',
    '[Win32]::ShowWindow($mainWindow, [Win32]::SW_RESTORE) | Out-Null',
    'Start-Sleep -Milliseconds 300',
    '[Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    'Start-Sleep -Milliseconds 500',

    '# Get window title',
    '$sb = New-Object System.Text.StringBuilder(512)',
    '[Win32]::GetWindowText($mainWindow, $sb, 512) | Out-Null',
    '$title = $sb.ToString()',
    '$debug += "TITLE=" + $title',

    '# Detect language',
    '$isSpanish = $true',
    'if ($title -match "Workstation" -and $title -notmatch "Estacion") { $isSpanish = $false }',
    '$debug += "LANG=" + $(if ($isSpanish) { "ES" } else { "EN" })',

    '# Step 1: Check if password dialog is showing by looking for Edit controls',
    '$hasEdit = $false',
    '$editChild = [IntPtr]::Zero',
    'do {',
    '  $editChild = [Win32]::FindWindowEx($mainWindow, $editChild, "Edit", $null)',
    '  if ($editChild -ne [IntPtr]::Zero) {',
    '    $hasEdit = $true',
    '    break',
    '  }',
    '} while ($editChild -ne [IntPtr]::Zero)',
    '$debug += "HAS_EDIT=" + $hasEdit',

    'if ($hasEdit) {',
    '  $debug += "STEP=PASSWORD_DIALOG"',
    '  # We are at the password dialog - enter VM password',
    '  [Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    '  Start-Sleep -Milliseconds 300',
    '',
    '  # Type password using WM_SETTEXT on the Edit control',
    '  [Win32]::SendMessage($editChild, [Win32]::WM_SETTEXT, [IntPtr]::Zero, "' + VM_PWD + '") | Out-Null',
    '  Start-Sleep -Milliseconds 300',
    '  $debug += "PWD_TYPED=true"',
    '',
    '  # Press Enter',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 50',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Seconds 3',
    '  $debug += "PWD_ENTER_SENT=true"',
    '}',
    '',
    '# Step 2: Wait for VM to start and look for settings dialog',
    '$debug += "STEP=WAITING_FOR_VM"',
    'Start-Sleep -Seconds 2',
    '',
    '# Refresh window title',
    '[Win32]::GetWindowText($mainWindow, $sb, 512) | Out-Null',
    '$title = $sb.ToString()',
    '$debug += "TITLE_AFTER_PWD=" + $title',
    '',
    '# Step 3: Open VM Settings via menu',
    '$debug += "STEP=OPENING_SETTINGS"',
    '[Win32]::SetForegroundWindow($mainWindow) | Out-Null',
    'Start-Sleep -Milliseconds 300',
    '',
    '# Use Alt key to access menu',
    'if ($isSpanish) {',
    '  # Alt+M for Maquina menu in Spanish',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int][char]"m", [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '} else {',
    '  # Alt+V for VM menu in English',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYDOWN, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int][char]"v", [IntPtr]::Zero) | Out-Null',
    '  Start-Sleep -Milliseconds 100',
    '  [Win32]::SendMessage($mainWindow, [Win32]::WM_KEYUP, [IntPtr]0x12, [IntPtr]::Zero) | Out-Null',
    '}',
    'Start-Sleep -Milliseconds 500',
    '',
    '# Press S for Settings (or Configuracion)',
    '[Win32]::SendMessage($mainWindow, [Win32]::WM_CHAR, [IntPtr][int][char]"s", [IntPtr]::Zero) | Out-Null',
    'Start-Sleep -Seconds 2',
    '$debug += "SETTINGS_MENU_SENT=true"',
    '',
    '# Step 4: Find Settings dialog and enter password',
    '$settingsWindow = [IntPtr]::Zero',
    '$callback2 = [Win32+EnumWindowsProc]{',
    '  param($hwnd, $lParam)',
    '  $procId = 0',
    '  [Win32]::GetWindowThreadProcessId($hwnd, [ref]$procId) | Out-Null',
    '  foreach ($p in $vmwareProcs) {',
    '    if ($p.Id -eq $procId) {',
    '      $len = [Win32]::GetWindowTextLength($hwnd)',
    '      if ($len -gt 0) {',
    '        $sb2 = New-Object System.Text.StringBuilder($len + 1)',
    '        [Win32]::GetWindowText($hwnd, $sb2, $sb2.Capacity) | Out-Null',
    '        $t = $sb2.ToString()',
    '        if ($t -ne $title -and $t -ne "" -and $t -notmatch "VMware Workstation$") {',
    '          $script:settingsWindow = $hwnd',
    '          return $false',
    '        }',
    '      }',
    '    }',
    '  }',
    '  return $true',
    '}',
    '[Win32]::EnumWindows($callback2, [IntPtr]::Zero) | Out-Null',

    'if ($settingsWindow -ne [IntPtr]::Zero) {',
    '  $debug += "SETTINGS_DIALOG=true"',
    '  [Win32]::SetForegroundWindow($settingsWindow) | Out-Null',
    '  Start-Sleep -Milliseconds 500',
    '',
    '  # Find Edit control for password',
    '$settingsEdit = [IntPtr]::Zero',
    'do {',
    '  $settingsEdit = [Win32]::FindWindowEx($settingsWindow, $settingsEdit, "Edit", $null)',
    '  if ($settingsEdit -ne [IntPtr]::Zero) { break }',
    '} while ($settingsEdit -ne [IntPtr]::Zero)',
    '',
    '  if ($settingsEdit -ne [IntPtr]::Zero) {',
    '    # Enter settings password',
    '    [Win32]::SendMessage($settingsEdit, [Win32]::WM_SETTEXT, [IntPtr]::Zero, "' + SETTINGS_PWD + '") | Out-Null',
    '    Start-Sleep -Milliseconds 300',
    '    # Press Enter',
    '    [Win32]::SendMessage($settingsWindow, [Win32]::WM_KEYDOWN, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Milliseconds 50',
    '    [Win32]::SendMessage($settingsWindow, [Win32]::WM_KEYUP, [IntPtr][int][Win32]::VK_RETURN, [IntPtr]::Zero) | Out-Null',
    '    Start-Sleep -Seconds 2',
    '    $debug += "SETTINGS_PWD_SENT=true"',
    '  }',
    '}',
    '',
    '# Output debug',
    'foreach ($d in $debug) { Write-Output $d }',
    'Write-Output "DATE_TO_SET=' + newDate + '"'
  ].join('\r\n');

  try {
    var raw = await exec(ps);
    var lines = (raw || '').split('\n').map(function(l) { return l.trim(); });
    var debug = {};
    for (var i = 0; i < lines.length; i++) {
      var line = lines[i];
      if (line.indexOf('=') > 0) {
        var eq = line.indexOf('=');
        var key = line.substring(0, eq);
        var val = line.substring(eq + 1);
        debug[key] = val;
      }
    }
    return {
      ok: !debug.ERROR,
      newDate: newDate,
      debug: debug,
      at: new Date().toISOString()
    };
  } catch (e) {
    return { ok: false, error: e.message, at: new Date().toISOString() };
  }
} };
